const P=(it,en)=>({it,en});
const projects=[
{id:'monoblock',name:'MONOBLOCK',type:P('Tesi · Exhibition design','Thesis · Exhibition design'),year:'2026',cover:'monoblock-48',subtitle:P('Il progetto si ferma al cancello della fabbrica.','Design stops at the factory gate.'),intro:P('Una sedia comune diventa il punto di partenza per interrogare il ciclo di vita degli oggetti. MONOBLOCK mette in scena la distanza tra una produzione ottimizzata e un fine vita ancora da progettare.','An everyday chair becomes the starting point for questioning the life cycle of objects. MONOBLOCK stages the gap between optimised production and an end of life that still needs to be designed.'),meta:P('Tesi di laurea · Design degli Interni\nPolitecnico di Milano · A.A. 2025/26\nRelatore: Marcello Galbiati','Bachelor’s thesis · Interior Design\nPolitecnico di Milano · A.Y. 2025/26\nSupervisor: Marcello Galbiati'),team:'Filippo Antonio Visentin',text:P('L’allestimento collega storia, materia e trasformazione. Strutture espositive, tende e un sistema di binari costruiscono un percorso in cui la sedia è letta come prodotto, risorsa e responsabilità. La stampa 3D rende visibile la possibilità di un nuovo ciclo materiale.','The exhibition connects history, matter and transformation. Display structures, curtains and a rail system form a journey where the chair is considered as product, resource and responsibility. 3D printing makes a new material cycle visible.'),gallery:['monoblock-46','monoblock-47','monoblock-49','monoblock-50','monoblock-51','monoblock-30','monoblock-31','monoblock-36','monoblock-37','monoblock-38','monoblock-39']},
{id:'bivacuum',name:'BIVACUUM',type:P('Architettura · Spazio minimo','Architecture · Minimum space'),year:'',cover:'bivacuum-01-hero-exterior-dusk',subtitle:P('Abitare la quota. Liberare lo spazio.','Living at altitude. Freeing up space.'),intro:P('Un rifugio per almeno otto persone, pensato per la Grignetta. Una struttura trasportabile e preassemblata accoglie un interno capace di cambiare tra il riposo e la vita condivisa.','A shelter for at least eight people, conceived for the Grignetta. A transportable, preassembled structure contains an interior that shifts between rest and shared life.'),meta:P('Bivacco alpino · Grignetta\nSistema modulare · Giorno / notte','Alpine shelter · Grignetta\nModular system · Day / night'),team:'Filippo Antonio Visentin, Anton Qerkini',text:P('Il soffitto diventa infrastruttura: i binari permettono di sospendere le amache e riconfigurare l’ambiente. Tavoli ripiegabili e sedute integrate liberano il pavimento. Involucro, fondazioni a vite e pannelli fotovoltaici orientabili sono parti di un unico sistema.','The ceiling becomes infrastructure: rails support hammocks and allow the room to be reconfigured. Folding tables and integrated seating free up the floor. The envelope, screw foundations and adjustable solar panels are parts of a single system.'),gallery:['bivacuum-14-interior-day','bivacuum-15-interior-night','bivacuum-06-sketch-grid','bivacuum-07-sketch-hammocks','bivacuum-11-section-day-long','bivacuum-13-section-night-long','bivacuum-16-envelope-stratigraphy','bivacuum-17-screw-foundation','bivacuum-18-pv-tilt']},
{id:'compluvio',name:'COMPLUVIO',type:P('Architettura · Paesaggio','Architecture · Landscape'),year:'',cover:'compluvio_render_esterno',subtitle:P('La forma segue l’acqua.','Form follows water.'),intro:P('Una serra sociale e terapeutica per Cascina Linterno, Milano. Due volte vetrate si incontrano in una linea di raccolta: l’acqua piovana diventa principio generativo dello spazio.','A social and therapeutic greenhouse for Cascina Linterno, Milan. Two glazed vaults meet along a collection line: rainwater becomes the space’s organising principle.'),meta:P('Cascina Linterno · Milano\nSerra sociale e terapeutica','Cascina Linterno · Milan\nSocial and therapeutic greenhouse'),team:'Filippo Antonio Visentin',text:P('La copertura convoglia la pioggia verso un serbatoio per l’irrigazione. Il progetto esplora un ciclo di recupero dell’acqua e un rapporto continuo tra coltivazione, incontro e paesaggio. La luce attraversa la struttura e accompagna le attività all’interno.','The roof channels rain towards a reservoir for irrigation. The project explores water recovery and a continuous relationship between cultivation, gathering and landscape. Light passes through the structure, supporting the activities within.'),gallery:['compluvio_render_interno_01','compluvio_render_interno_02','compluvio_sezioni_tipo','compluvio_assonometria_luogo']},
{id:'poliedro',name:'POLIEDRO',type:P('Product design · Arredo urbano','Product design · Urban furniture'),year:'2026',cover:'poliedro_render_notturno',subtitle:P('Una geometria. Molti modi di stare insieme.','One geometry. Many ways of being together.'),intro:P('Un sistema di sedute modulari in calcestruzzo che costruisce luoghi di relazione. La matrice esagonale permette aggregazioni aperte, mentre una lampada trasforma il centro della composizione in un punto d’incontro.','A system of modular concrete seats that creates places for connection. A hexagonal matrix allows open-ended arrangements, while a lamp turns the centre of the composition into a meeting point.'),meta:P('Laboratorio di sintesi finale · A.A. 2025/26\nSistema modulare di sedute e illuminazione','Final design studio · A.Y. 2025/26\nModular seating and lighting system'),team:'Filippo Antonio Visentin, Lawrence Sedra, Anna Varsavia, Nina Rosa Patanè',text:P('Altezze, cavità e appoggi differenziano l’uso mantenendo una famiglia formale comune. La luce introduce un secondo tempo di vita dello spazio pubblico. L’allestimento A matter of presence sviluppa il racconto spaziale di questa ricerca.','Heights, cavities and supports create different uses within a shared formal family. Light introduces a second rhythm to public space. The exhibition A matter of presence develops the spatial narrative of this research.'),gallery:['poliedro_composizione_dettaglio','poliedro_dettaglio_seduta_03','poliedro_dettaglio_seduta_04','poliedro_lampada','poliedro_schizzo_concept']},
{id:'presence',name:'A MATTER OF PRESENCE',type:P('Exhibition design · POLIEDRO','Exhibition design · POLIEDRO'),year:'2026',cover:'presence_interno_01',subtitle:P('La materia si moltiplica nello sguardo.','Matter multiplies through perception.'),intro:P('L’allestimento di POLIEDRO traduce la presenza del materiale in un’esperienza immersiva. Specchi, penombra e un paesaggio minerale costruiscono uno spazio sospeso tra montagna e interno.','The exhibition for POLIEDRO translates material presence into an immersive experience. Mirrors, low light and a mineral landscape create a space suspended between mountain and interior.'),meta:P('Allestimento del progetto POLIEDRO\nLaboratorio di sintesi finale · A.A. 2025/26','Exhibition for POLIEDRO\nFinal design studio · A.Y. 2025/26'),team:'Filippo Antonio Visentin, Lawrence Sedra, Anna Varsavia, Nina Rosa Patanè',text:P('Le superfici riflettenti prolungano i moduli e frammentano i punti di vista. Al centro, una zona di sosta riunisce le persone; tende e luce controllano il rapporto con l’esterno. Il visitatore attraversa la materia prima di leggerla come oggetto.','Reflective surfaces extend the modules and fragment viewpoints. A central resting area brings people together; curtains and light control the relationship with the outside. Visitors encounter matter before reading it as an object.'),gallery:['presence_interno_02','presence_interno_03','presence_prospetti']},
{id:'oltreetrusco',name:'OLTRE ETRUSCO',type:P('Exhibition design · Cultura','Exhibition design · Culture'),year:'2025',cover:'oltreetrusco_render_sala3_grande',subtitle:P('Attraversare un confine. Poi un altro.','Crossing a boundary. Then another.'),intro:P('Un percorso espositivo che interpreta lo sconfinamento tra passato e presente. Da una sequenza guidata a uno spazio libero, i limiti si dissolvono progressivamente e cambiano il modo di incontrare i reperti.','An exhibition journey exploring boundaries between past and present. From a guided sequence to an open space, boundaries gradually dissolve and change the way visitors encounter the artefacts.'),meta:P('Politecnico di Milano · A.A. 2024/25\nAllestimento museale · Sistema espositivo Oltre','Politecnico di Milano · A.Y. 2024/25\nMuseum exhibition · Oltre display system'),team:'Filippo Antonio Visentin, Anton Qerkini, Noè Bartolini, Jacopo Dellanoce, Luca Mastromatteo',text:P('Il sistema Oltre usa strutture metalliche modulari e supporti regolabili. La progressione delle sale accompagna il visitatore da un percorso obbligato a una scoperta più autonoma, fino a soglie leggere e tende.','The Oltre system uses modular metal structures and adjustable supports. The progression of rooms guides visitors from a prescribed route towards independent discovery, ending with light thresholds and curtains.'),gallery:['oltreetrusco_render_sala2','oltreetrusco_render_sala3','oltreetrusco_render_sala4_01','oltreetrusco_render_sala4_02','oltreetrusco_assonometria_01','oltreetrusco_esploso_struttura']},
{id:'soundplace',name:'SOUNDPLACE',type:P('Service design · Spazio pubblico','Service design · Public space'),year:'',cover:'soundplace_render_parco',subtitle:P('Un albero, due sedute, una possibilità.','A tree, two seats, a possibility.'),intro:P('Un luogo mobile per incontrarsi e condividere musica a Morbegno. Soundplace unisce l’idea del suono a quella del focolare: un piccolo dispositivo urbano per costruire relazioni.','A mobile place for meeting and sharing music in Morbegno. Soundplace brings together sound and the idea of a fireplace: a small urban device for building relationships.'),meta:P('Morbegno · Ponte Vanoni\nWalking Tree · 80 × 160 cm','Morbegno · Ponte Vanoni\nWalking Tree · 80 × 160 cm'),team:'Filippo Antonio Visentin, Francisco Junior Cuello Ramirez, Monow Sarkar',text:P('Il modulo integra un albero e un risonatore passivo per smartphone, senza alimentazione elettrica. Lo storyboard descrive un servizio ipotizzato di prenotazione, attivazione e condivisione: l’oggetto diventa parte di un’esperienza collettiva.','The module integrates a tree and a passive smartphone resonator with no electrical power supply. The storyboard describes a proposed booking, activation and sharing service: the object becomes part of a collective experience.'),gallery:['soundplace_assonometria','soundplace_luogo_ponte','soundplace_storyboard']}
];

